const slots = $json.openSlots ?? [];
const contacts = $json.eligibleContacts ?? [];
const matches = slots.map((slot) => {
  const eligible = contacts.filter((contact) => contact.contactAllowed && contact.eligibleFor === slot.slotType).sort((a, b) => Number(b.lastTouchDays ?? 0) - Number(a.lastTouchDays ?? 0));
  return { slotId: slot.slotId, startsAt: slot.startsAt, slotType: slot.slotType, suggestedContact: eligible[0] ?? null, nextAction: eligible[0] ? 'Create approved short-notice fill task.' : 'No eligible fake contact found.' };
});
return matches.map((match) => ({ json: match }));
